scripts.mana:
"""Bounded finite Pass C tests for Grixistax___October_2026 (Deck 27). Seeded finite Monte Carlo goldfish of
mana deployment (fixed seed 27, fixed N); exact hypergeometric where closed form exists. Not an effect-aware game
simulation; no opponent model; no win rates."""
import json,re,random,sys
from math import comb
W='/workspace/d27w/'
def load(p):
    out=[]
    for l in open(p):
        m=re.match(r'(\d+)x (.+?)( \[Commander\])?$',l.strip())
        if m and not m.group(3): out+=[m.group(2)]*int(m.group(1))
    return out
base=load(W+'base.txt'); assert len(base)==98
def swap(d,add,cut):
    d=d[:]; d.remove(cut); d.append(add); return d
CFG={"baseline":base,
     "plus_Arcane_Signet_minus_Mox_Amber":swap(base,"Arcane Signet","Mox Amber"),
     "plus_Talisman_of_Indulgence_minus_Mox_Amber":swap(base,"Talisman of Indulgence","Mox Amber"),
     "plus_Arcane_Signet_minus_Overburden_keep_Amber":swap(base,"Arcane Signet","Overburden")}
BASICS={"Island":"U","Swamp":"B","Mountain":"R"}
FETCH={"Arid Mesa","Bloodstained Mire","Flooded Strand","Marsh Flats","Misty Rainforest","Polluted Delta","Scalding Tarn","Verdant Catacombs","Wooded Foothills"}
DUAL={"Badlands":"BR","Blood Crypt":"BR","Steam Vents":"UR","Volcanic Island":"UR","Underground Sea":"UB","Watery Grave":"UB","Morphic Pool":"UB",
      "City of Brass":"UBR","Mana Confluence":"UBR","Command Tower":"UBR","Otawara, Soaring City":"U","Ancient Tomb":"CC","Phyrexian Tower":"C","Gemstone Caverns":"C"}
LANDS=set(BASICS)|FETCH|set(DUAL)
assert sum(c in LANDS for c in base)==26, sum(c in LANDS for c in base)
# rocks: name -> (cost, colors produced, persistent?)
ROCK={"Sol Ring":(1,"CC"),"Talisman of Creativity":(2,"UR"),"Talisman of Dominance":(2,"UB"),"Talisman of Indulgence":(2,"BR"),"Arcane Signet":(2,"UBR")}
ZERO={"Chrome Mox","Mox Diamond","Mox Opal","Mox Amber"}
LEG={"Ragavan, Nimble Pilferer":(1,"R"),"Ashiok, Dream Render":(3,"UB"),"Narset, Parter of Veils":(3,"U"),"Sheoldred, the Apocalypse":(4,"B")}
def land_colors(c,state,entered_turn,t):
    if state=="Contamination": return "B"
    if state=="Blood Moon":
        return BASICS.get(c,"R")
    if state=="Back to Basics" and c not in BASICS and c not in FETCH and entered_turn<t: return None
    if c in BASICS: return BASICS[c]
    if c in FETCH: return "UBR"   # every fetch here finds a typed dual or basic of each relevant colour
    return DUAL[c]
def game(deck,rnd,state,turns=4):
    d=deck[:]; rnd.shuffle(d)
    hand=d[:7]; lib=d[7:]; bf_lands=[]; rocks=[]; legend_colors=set(); amber=False; zero=[]
    out=[]
    for t in range(1,turns+1):
        if t>1: hand.append(lib.pop(0))
        # land drop (fetch resolved to dual; prefer basics under B2B/Moon)
        lh=[c for c in hand if c in LANDS]
        if lh:
            pref=sorted(lh,key=lambda c:(0 if (state in("Blood Moon","Back to Basics") and (c in BASICS or c in FETCH)) else 1, c=="Gemstone Caverns"))
            L=pref[0]; hand.remove(L)
            if L in FETCH and state in ("Blood Moon","Back to Basics"):
                bf_lands.append(("basicfetch",t))
            else: bf_lands.append((L,t))
        # zero-cost artifacts
        for z in list(hand):
            if z=="Mox Diamond" and sum(c in LANDS for c in hand)>=1:
                hand.remove(z); hand.remove([c for c in hand if c in LANDS][0]); zero.append(z)
            elif z=="Chrome Mox" and any(c not in LANDS and c not in ROCK and c not in ZERO and c not in("Lotus Petal","Lion's Eye Diamond","Grim Monolith","Mana Vault","Sol Ring") for c in hand if c!=z):
                hand.remove(z); x=[c for c in hand if c not in LANDS and c not in ROCK and c not in ZERO][0]; hand.remove(x); zero.append(z)
            elif z in ("Mox Opal","Mox Amber"):
                hand.remove(z); zero.append(z)
        def pool():
            srcs=[]
            for L,et in bf_lands:
                if L=="basicfetch": srcs.append("UBR" if state=="Back to Basics" else "UBR" if state!="Contamination" else "B")
                else:
                    col=land_colors(L,state,et,t)
                    if col is None: continue
                    if col=="CC": srcs+= ["C","C"] if state!="Contamination" else ["B","B"]
                    else: srcs.append(col)
            if state=="Artifact hate": return srcs
            nart=len(rocks)+len(zero)
            for r in rocks: srcs+= ["C","C"] if ROCK[r][1]=="CC" else [ROCK[r][1]]
            for z in zero:
                if z in("Chrome Mox","Mox Diamond"): srcs.append("UBR")
                elif z=="Mox Opal" and nart>=3: srcs.append("UBR")
                elif z=="Mox Amber" and legend_colors: srcs.append("".join(sorted(legend_colors)))
            return srcs
        # cast rocks while affordable (greedy, highest output first)
        spent=0
        for r in sorted([c for c in hand if c in ROCK],key=lambda c:ROCK[c][0]):
            if len(pool())-spent>=ROCK[r][0]:
                hand.remove(r); rocks.append(r); spent+=ROCK[r][0]
                if state!="Artifact hate": spent-=0  # new rock usable immediately (untapped)
        avail=len(pool())-spent
        # cast a colored legend enabler if affordable (cheapest first), commanders from command zone at 5
        cmd=False
        for c in sorted([c for c in hand if c in LEG],key=lambda c:LEG[c][0]):
            if avail>=LEG[c][0]:
                hand.remove(c); legend_colors|=set(LEG[c][1]); avail-=LEG[c][0]; break
        P=pool()
        cmd_ok=len(P)-spent>=5 and any("B" in s for s in P)
        if cmd_ok and not cmd: legend_colors|=set("B")
        amber_live=("Mox Amber" in zero) and bool(legend_colors) and state!="Artifact hate"
        P2=pool(); n=len(P2)
        out.append(dict(mana=n,U=sum('U' in s for s in P2),R=any('R' in s for s in P2),B=any('B' in s for s in P2),cmd=cmd_ok,amber_in=("Mox Amber" in zero),amber_live=amber_live))
    return out
STATES=["no lock","Contamination","Blood Moon","Back to Basics","Artifact hate"]
def run(deck,state,seed=27,R=40000):
    rnd=random.Random(seed); acc={t:dict(mana=0,UU=0,U=0,R=0,cmd5=0,amber_in=0,amber_live=0) for t in range(1,5)}
    for _ in range(R):
        g=game(deck,rnd,state)
        for t,o in enumerate(g,1):
            a=acc[t]; a['mana']+=o['mana']; a['UU']+=o['U']>=2; a['U']+=o['U']>=1; a['R']+=o['R']; a['cmd5']+=o['cmd']; a['amber_in']+=o['amber_in']; a['amber_live']+=o['amber_live']
    res={}
    for t,a in acc.items():
        r={"mean_mana_sources_after_deploy":round(a['mana']/R,3),"P_U_available":round(a['U']/R,4),"P_UU_available":round(a['UU']/R,4),"P_R_available":round(a['R']/R,4),"P_five_mana_with_B_for_Tevesh":round(a['cmd5']/R,4)}
        if a['amber_in']: r["P_Mox_Amber_live_given_deployed"]=round(a['amber_live']/a['amber_in'],4)
        res[f"turn {t}"]=r
    return res
out={"deck":"Grixistax___October_2026","seed":27,"games_per_cell":40000,"on":"the play, no mulligans, 7 + (t-1) cards seen",
 "method":"Seeded finite Monte Carlo goldfish of mana deployment only. Each turn: one land drop (fetches resolved to a typed dual/basic; under Blood Moon and Back to Basics fetches find a basic of any colour), zero-cost Moxen deployed when their condition is met (Mox Diamond discards a spare land; Chrome Mox imprints a spare nonartifact nonland card; Mox Opal live at three artifacts; Mox Amber live only once a colored legendary creature or planeswalker is on the battlefield - Ragavan, Ashiok, Narset, Sheoldred, or a commander cast at five mana), Sol Ring/Talismans/Arcane Signet cast greedily when affordable, cheapest colored legend cast when affordable. Mana Vault, Grim Monolith, Lotus Petal, Lion's Eye Diamond, Dark Ritual, Culling the Weak, Jeska's Will, Gemstone Caverns luck counter and Ancient Tomb under Damping Sphere are ignored (conservative). Lock states are applied from turn 1 as a worst case for the own deck: Contamination = every land taps for B only; Blood Moon = nonbasics tap for R only; Back to Basics = nonbasic non-fetch lands only produce mana on the turn they enter; Artifact hate = opposing Null Rod / Collector Ouphe / Stony Silence class shuts every artifact mana source. Mox Amber with only Karn produces no mana (Karn is colorless); Karn is not counted as an enabler.",
 "results":{}}
for k,d in CFG.items():
    out["results"][k]={s:run(d,s) for s in STATES}
json.dump(out,open(W+'meas27_mana.json','w'),indent=1)
for k in CFG:
    for s in STATES:
        print(k[:45].ljust(45),s.ljust(15),{t:(v["mean_mana_sources_after_deploy"],v["P_U_available"],v["P_UU_available"],v["P_five_mana_with_B_for_Tevesh"],v.get("P_Mox_Amber_live_given_deployed")) for t,v in out["results"][k][s].items()})

scripts.tokens:
"""Token-engine / Opposition deployment proxy for Deck 27 (seeded finite goldfish, seed 27). Reuses the mana model of meas27.py."""
import json,random,sys
sys.argv=['x']; src=open('/workspace/d27w/gen/meas27.py').read().split('STATES=[')[0]
exec(src)
cand=load(W+'cand.txt'); OPP=load(W+'alt/Grixistax___October_2026_staged_plus_Opposition_minus_StaticOrb_20261023.txt'); assert len(cand)==98
def run2(deck,state,seed=27,R=40000):
    rnd=random.Random(seed); acc={t:[0,0,0] for t in range(1,5)}
    for _ in range(R):
        d=deck[:]; rnd.shuffle(d)
        # replay the deterministic deployment from meas27.game on the same shuffle
        r2=random.Random(); r2.shuffle=lambda x,dd=d: x.__setitem__(slice(None),dd)
        g=game(deck,r2,state)
        for t,o in enumerate(g,1):
            seen=d[:6+t]
            bb=("Bitterblossom" in seen[:6+t-0]) and any(o2['B'] and o2['mana']>=2 for o2 in g[:t])
            tev=any(o2['cmd'] for o2 in g[:t])
            opp=("Opposition" in seen) and any(o2['U']>=2 and o2['mana']>=4 for o2 in g[:t])
            acc[t][0]+=tev; acc[t][1]+=(tev or bb); acc[t][2]+=opp
    return {f"turn {t}":{"P_token_engine_online_Tevesh_only":round(a[0]/R,4),"P_token_engine_online_Tevesh_or_Bitterblossom":round(a[1]/R,4),"P_Opposition_seen_and_castable":round(a[2]/R,4)} for t,a in acc.items()}
from math import comb
def p_seen(n,K=1,N=98): return 1-comb(N-K,n)/comb(N,n)
out={"deck":"Grixistax___October_2026","seed":27,"games_per_cell":40000,
 "method":"Same deployment model and lock-state definitions as meas27_mana.json. A token engine is online on turn t if Tevesh was castable (five mana including B) on some turn <= t, or Bitterblossom was among the cards seen and two mana including B was available on some turn <= t. Opposition is castable if seen and four mana including two U-capable sources was available on some turn <= t. Tutors (Demonic Tutor, Vampiric Tutor, Imperial Seal, Diabolic Intent, Gamble, Beseech the Mirror, Wishclaw Talisman) are ignored, so single-card probabilities are lower bounds.",
 "P_specific_card_seen_by_turn":{f"turn {t}":round(p_seen(6+t),4) for t in range(1,5)},
 "candidate":{s:run2(cand,s) for s in ["no lock","Contamination","Blood Moon","Artifact hate"]},"staged_Opposition_alt":{s:run2(OPP,s) for s in ["no lock","Contamination","Blood Moon","Artifact hate"]}}
# Static Orb comparison on the baseline
def so(deck,state,seed=27,R=40000):
    rnd=random.Random(seed); acc={t:0 for t in range(1,5)}
    for _ in range(R):
        d=deck[:]; rnd.shuffle(d)
        r2=random.Random(); r2.shuffle=lambda x,dd=d: x.__setitem__(slice(None),dd)
        g=game(deck,r2,state)
        for t in range(1,5): acc[t]+=("Static Orb" in d[:6+t]) and any(o['mana']>=3 for o in g[:t])
    return {f"turn {t}":round(a/R,4) for t,a in acc.items()}
out["baseline_P_Static_Orb_seen_and_castable"]={s:so(base,s) for s in ["no lock","Contamination","Blood Moon","Artifact hate"]}
out["baseline_P_token_engine_online_Tevesh_only"]={s:{k:v["P_token_engine_online_Tevesh_only"] for k,v in run2(base,s).items()} for s in ["no lock","Contamination","Blood Moon","Artifact hate"]}
json.dump(out,open(W+'meas27_tokens.json','w'),indent=1)
print(json.dumps(out,indent=0)[:3000])
